    algorithms: {
      numbers: [3, 7, 11, 15, 19, 23, 27],
      prerequisite: 'First understand variables, comparisons, conditions, loops, collections, indexes, and functions. Finish one programming track, then practice these steps.',
      definition: 'Binary search is a way to find a target in a sorted sequence. Check the middle. If the target is smaller, keep only the left half. If it is larger, keep only the right half. Repeat until you find it or no items remain.',
      words: [['Target', 'The value you want to find.'], ['low', 'The first index still being considered.'], ['high', 'The last index still being considered.'], ['mid', 'The middle index between low and high.'], ['Sorted', 'Arranged in an order that matches the comparison, such as ascending numbers.'], ['Not found', 'The search interval is empty; this example returns -1.']],
      steps: [
        { title: 'Write an algorithm in ordinary words', description: 'First, check the items one by one. That is linear search. You can use it even if the items are not sorted. A binary search needs a sorted sequence because the middle comparison tells you which half can be discarded.', question: 'Which search requires the input to be sorted for this numeric example?', options: ['Linear search', 'Binary search', 'Neither'], answer: 1, why: 'Binary search relies on sorted order to exclude half of the candidate items.', hint: 'The middle comparison must describe the values on both sides.' },
        { title: 'Follow the bounds and the middle', description: 'For target 23, start low at 0 and high at 6. mid is 3, whose value is 15. Since 23 is larger, move low to mid + 1, which is 4. The next mid is 5, whose value is 23. The result is index 5.', question: 'After checking 15 while searching for 23, which half remains?', options: ['Indexes 0–2', 'Only index 3', 'Indexes 4–6'], answer: 2, why: '23 is greater than 15, so earlier values and the middle cannot match in this ascending sequence.', hint: 'Move to the values larger than the checked middle.' },
        { title: 'Handle a missing target and compare the work', description: 'For target 17, check 15, then 23, then 19. The next bounds cross, so nothing remains and the result is -1. Linear search may inspect n items. Binary search takes O(log n) comparisons on a sorted, efficiently indexed sequence. Sorting the input first has its own cost.', question: 'What should this algorithm return if the target is absent?', options: ['-1', 'Always 0', 'The target value anyway'], answer: 0, why: '-1 is the not-found marker used by these examples. A valid index is zero or greater.', hint: 'Choose the value that cannot be a real sequence index.' }
      ],
      code: {
        javascript: 'function binarySearch(numbers, target) {\n  let low = 0;\n  let high = numbers.length - 1;\n  while (low <= high) {\n    const mid = low + Math.floor((high - low) / 2);\n    if (numbers[mid] === target) return mid;\n    if (numbers[mid] < target) low = mid + 1;\n    else high = mid - 1;\n  }\n  return -1;\n}\nconsole.log(binarySearch([3, 7, 11, 15, 19, 23, 27], 23));',
        java: 'public class Main {\n    static int binarySearch(int[] numbers, int target) {\n        int low = 0;\n        int high = numbers.length - 1;\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            if (numbers[mid] == target) return mid;\n            if (numbers[mid] < target) low = mid + 1;\n            else high = mid - 1;\n        }\n        return -1;\n    }\n    public static void main(String[] args) {\n        int[] numbers = {3, 7, 11, 15, 19, 23, 27};\n        System.out.println(binarySearch(numbers, 23));\n    }\n}',
        python: 'def binary_search(numbers, target):\n    low = 0\n    high = len(numbers) - 1\n    while low <= high:\n        mid = low + (high - low) // 2\n        if numbers[mid] == target:\n            return mid\n        if numbers[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\nprint(binary_search([3, 7, 11, 15, 19, 23, 27], 23))',
        php: '<?php\nfunction binarySearch(array $numbers, int $target): int {\n    $low = 0;\n    $high = count($numbers) - 1;\n    while ($low <= $high) {\n        $mid = $low + intdiv($high - $low, 2);\n        if ($numbers[$mid] === $target) return $mid;\n        if ($numbers[$mid] < $target) $low = $mid + 1;\n        else $high = $mid - 1;\n    }\n    return -1;\n}\necho binarySearch([3, 7, 11, 15, 19, 23, 27], 23);'
      },
      practice: 'Run the example for 3, 23, 27, and 17. Expect indexes 0, 5, 6, and -1. Then test an empty sequence. Use sorted whole numbers; the PHP version expects a zero-based, contiguous indexed array. Repeated values can return any matching index, not necessarily the first.',
      sources: [['Python bisection documentation', 'https://docs.python.org/3/library/bisect.html'], ['Java Arrays binarySearch contract', 'https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/util/Arrays.html#binarySearch(int%5B%5D,int)']]
    },
